-- Restore 68 missing complete reference groups (136 numeric loot choices)
-- from the archived LoA world. All items were checked present and below the
-- level-100 quarantine. Existing complete groups win; never merge partial odds.
-- Original chance/count/group values are preserved. Empty source lootmode is
-- SET value zero (all modes), not a guaranteed or difficulty-specific drop.
CREATE TEMPORARY TABLE codex_missing_ref_restore LIKE reference_loot_template;
CREATE TEMPORARY TABLE codex_missing_ref_groups AS
SELECT r.entry FROM codex_missing_ref_restore r LEFT JOIN item_template i ON i.entry=r.item
GROUP BY r.entry HAVING SUM(i.entry IS NULL OR i.RequiredLevel>=100)=0;
SELECT r.entry,r.item,r.ChanceOrQuestChance,r.lootmode,r.groupid,r.mincountOrRef,r.maxcount
FROM codex_missing_ref_restore r JOIN codex_missing_ref_groups eligible ON eligible.entry=r.entry
WHERE NOT EXISTS(SELECT 1 FROM reference_loot_template live WHERE live.entry=r.entry);
DROP TEMPORARY TABLE codex_missing_ref_restore;
DROP TEMPORARY TABLE codex_missing_ref_groups;
